import { useCallback, useState } from 'react';
import { JxChip, JxTagInput } from '@jinx-ui/react';

export interface ArticleTagPickerProps {
  value?: string[];
  defaultValue?: string[];
  label?: string;
  placeholder?: string;
  emptyText?: string;
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagPicker({
  value,
  defaultValue = [],
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  emptyText = 'Пока нет ни одного тега',
  onChange,
}: ArticleTagPickerProps) {
  const [innerTags, setInnerTags] = useState<string[]>(defaultValue);
  const tags = value ?? innerTags;

  const commit = useCallback(
    (next: string[]) => {
      if (value === undefined) {
        setInnerTags(next);
      }
      onChange?.(next);
    },
    [onChange, value],
  );

  const removeTag = useCallback(
    (tag: string) => {
      commit(tags.filter((item) => item !== tag));
    },
    [commit, tags],
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
      <span style={{ color: 'var(--jx-text-2)' }}>{label}</span>

      <JxTagInput
        ariaLabel={label}
        placeholder={placeholder}
        value={tags}
        onValueChange={commit}
      />

      {tags.length === 0 ? (
        <span style={{ color: 'var(--jx-text-3)' }}>{emptyText}</span>
      ) : (
        <div
          role="list"
          aria-label="Выбранные теги"
          style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
        >
          {tags.map((tag) => (
            <JxChip key={tag} role="listitem" removable onRemove={() => removeTag(tag)}>
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

